-- hasta tener la imagen del personaje, cada uno se ve con la portada de marca (igual que un ejercicio que crea Jeff sin imagen).
-- Lista, nombres de archivo de las imágenes y textos para generarlas: docs/EJERCICIOS_NUEVOS.md.
-- Igual que la 0040: se cargan en cada espacio de coach y NO duplican: si Jeff ya tiene uno con el mismo nombre (sin importar
-- mayúsculas), solo se le ponen las series sugeridas si no las tenía. Necesita 0039. Compatible con main (solo filas nuevas).
-- Correrla cuando Cristian o Jeff aprueben la lista. Se puede correr otra vez sin duplicar.
-- Revertir (solo los que no se han usado en rutinas ni planes y siguen sin imagen): crear y llenar _preset como abajo y luego
--   delete from public.exercises e using _preset p where lower(e.name) = lower(p.name) and e.image is null
--     and not exists (select 1 from public.template_items t where t.exercise_id = e.id) and not exists (select 1 from public.plan_items i where i.exercise_id = e.id);

create temporary table _preset (name text, category text, muscle text, equipment text, difficulty smallint, instructions text, sets smallint, reps text);

update public.exercises e set sugg_sets = coalesce(e.sugg_sets, p.sets), sugg_reps = coalesce(e.sugg_reps, p.reps)
  from _preset p where lower(trim(e.name)) = lower(p.name);

select w.id, p.name, p.category, p.muscle, p.equipment, p.difficulty, p.instructions, p.sets, p.reps
from public.workspaces w cross join _preset p
where not exists (select 1 from public.exercises e where e.workspace_id = w.id and lower(trim(e.name)) = lower(p.name));
drop table _preset;
